@startuml

class Well {
  + code : string
  + pollutionRate() : float
}

class OnshoreWell extends Well {
  + surfaceExtension : float
}

class OffshoreWell extends Well {
  + yearOfInstallation : int
  + pollutionRate() : float
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

class Extraction {
  + quantity : float
}

Well "0..*" -- "0..*" Company : extraction
Extraction "1" -- "1" Well : refersTo
Extraction "1" -- "1" Company : performedBy
OffshoreWell "*" -- "0..1" GeographicalArea : locatedIn

@enduml

